
const DATA_B64=null;
const DATA_URL="data.json.gz";
let DB=null,STR=null,DB_RECORD=null,updatePromise=null,lastVersionCheckAt=0,playerRefs=[],playerSearchIndex=[],currentPid=null,currentAll=[],filtered=[],shown=60,sortMode='new',deferredInstall=null;
const databaseUpdateDiagnostics={localVersion:null,availableVersion:null,lastAttempt:null,lastSuccess:null,lastUpdated:null,lastError:null,lastReason:null};
const UPDATE=WZDBUpdate;
const CORE=WZAppCore;
function eventDateForRow(season,rowIndex){const ei=eventFromRow(season,rowIndex);return ei===null?'':eventData(season,ei)?.eventDate||''}
function sortResultRefs(rows,direction=sortMode){const model=(rows||[]).map(([season,row,rowIndex],fallback)=>{const order=Number.isInteger(rowIndex)?rowIndex:fallback;return {season,order,eventDate:eventDateForRow(season,order),ref:[season,row,rowIndex]}});return CORE.sortPlayerResults(model,direction).map(record=>record.ref)}
const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const norm=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/ł/g,'l').trim().replace(/\s+/g,' ');
const clean=s=>String(s??'').trim().replace(/\s+/g,' '), val=i=>i?STR[i]:'';
const sleep=()=>new Promise(r=>setTimeout(r,0));
function b64bytes(s){const bin=atob(s),a=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)a[i]=bin.charCodeAt(i);return a}
function toast(msg){const t=$('toast');t.textContent=msg;t.classList.remove('hidden');clearTimeout(toast.t);toast.t=setTimeout(()=>t.classList.add('hidden'),2600)}
function progress(on,title='',detail='',pct=0){$('progress').classList.toggle('hidden',!on);if(on){$('progressTitle').textContent=title;$('progressDetail').textContent=detail;$('progressBar').style.width=Math.max(0,Math.min(100,pct))+'%'}}
function setProgress(title,detail,pct){progress(true,title,detail,pct)}
function fmtDate(s){if(!s)return '';const m=String(s).match(/^(\d{4})-(\d{2})-(\d{2})/);return m?`${m[3]}.${m[2]}.${m[1]}`:s}
function fmtBirthDate(s){return UPDATE.formatBirthDateWithAge(s)}
function excelDate(v){const s=clean(v);if(!s||s==='?'||s==='#VALUE!'||s==='-')return '';if(/^\d+(?:\.\d+)?$/.test(s)){const n=Number(s);if(n>10000&&n<80000){const d=new Date(Date.UTC(1899,11,30)+Math.floor(n)*86400000);return d.toISOString().slice(0,10)}}return s}
function basePoints(s){return CORE.basePoints(s)}
function getJSON(k,d){try{return JSON.parse(localStorage.getItem(k)||'')||d}catch{return d}}
function favorites(){return getJSON('wz2:favs',[])} function recents(){return getJSON('wz2:recent',[])}
function setList(k,a){try{localStorage.setItem(k,JSON.stringify(a))}catch{}}
function findPidByKey(k){return DB.players.findIndex(p=>p[3]===k)}

async function ungzipBytes(bytes){if(!('DecompressionStream'in window))throw Error('Przeglądarka nie obsługuje dekompresji GZIP. Użyj aktualnego Chrome, Edge lub Safari.');const s=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));return await new Response(s).text()}
async function loadDefault(){let text;if(DATA_B64){text=await ungzipBytes(b64bytes(DATA_B64))}else{const r=await fetch(DATA_URL);if(!r.ok)throw Error('Nie można odczytać wbudowanej bazy.');const s=r.body.pipeThrough(new DecompressionStream('gzip'));text=await new Response(s).text()}return JSON.parse(text)}
function openIDB(){return new Promise((res,rej)=>{if(!('indexedDB'in window)){rej(Error('Brak IndexedDB'));return}const q=indexedDB.open('wyniki-zuzlowe-v2',1);q.onupgradeneeded=()=>q.result.createObjectStore('kv');q.onsuccess=()=>res(q.result);q.onerror=()=>rej(q.error)})}
async function idbGet(k){const db=await openIDB();return await new Promise((res,rej)=>{const q=db.transaction('kv').objectStore('kv').get(k);q.onsuccess=()=>res(q.result);q.onerror=()=>rej(q.error)})}
async function idbPut(k,v){const db=await openIDB();return await new Promise((res,rej)=>{const q=db.transaction('kv','readwrite').objectStore('kv').put(v,k);q.onsuccess=()=>res();q.onerror=()=>rej(q.error)})}
async function idbDel(k){const db=await openIDB();return await new Promise((res,rej)=>{const q=db.transaction('kv','readwrite').objectStore('kv').delete(k);q.onsuccess=()=>res();q.onerror=()=>rej(q.error)})}
async function saveCustomDB(db,metadata={},compressedBytes=null){const now=new Date().toISOString();let blob,encoding;if(compressedBytes){blob=new Blob([compressedBytes],{type:'application/gzip'});encoding='gzip'}else{const txt=JSON.stringify(db);if('CompressionStream'in window){const s=new Blob([txt]).stream().pipeThrough(new CompressionStream('gzip'));blob=await new Response(s).blob();encoding='gzip'}else{blob=new Blob([txt],{type:'application/json'});encoding='text'}}const record={blob,encoding,source:db.source,savedAt:now,built:metadata.built||db.built||now,wzdb_sha256:metadata.wzdb_sha256||null,source_sha256:metadata.source_sha256||null,lastChecked:metadata.lastChecked||null,lastUpdatedAt:metadata.lastUpdatedAt||now};await idbPut('customDB',record);DB_RECORD=record;return record}
async function loadStoredDB(){try{const record=await idbGet('customDB');if(!record||!record.blob)return null;let text;if(record.encoding==='gzip'){const s=record.blob.stream().pipeThrough(new DecompressionStream('gzip'));text=await new Response(s).text()}else text=await record.blob.text();return {db:JSON.parse(text),record}}catch(e){console.warn('Nie można odczytać lokalnej bazy WZDB.',e);return null}}
async function loadCustomDB(){const stored=await loadStoredDB();return stored?.db||null}

function renderDatabaseMeta(){if(!DB)return;const automatic=!!DB_RECORD?.wzdb_sha256;$('dbStatus').textContent=automatic?'Automatyczna aktualizacja aktywna':'Baza lokalna • oczekuje na synchronizację';$('dbVersion').textContent=UPDATE.formatLocalDateTime(DB_RECORD?.built||DB.built);$('dbLastChecked').textContent=UPDATE.formatLocalDateTime(DB_RECORD?.lastChecked);if(automatic){$('sourceName').textContent='Automatyczna baza WZDB';$('dbInfo').textContent=`${DB.stats.rows.toLocaleString('pl-PL')} wyników • ${UPDATE.formatLocalDateTime(DB_RECORD.built)}`}}
function validateDownloadedDB(db){if(!db||db.version!==4||!Array.isArray(db.strings)||db.strings[0]!==''||!Array.isArray(db.players)||!db.years||typeof db.years!=='object'||!db.stats||!Number.isFinite(db.stats.rows)||!Number.isFinite(db.stats.players))throw Error('Pobrany plik nie jest prawidłową bazą WZDB v4.');return db}
async function parseWZDB(bytes){return validateDownloadedDB(JSON.parse(await ungzipBytes(bytes)))}
async function activateUpdatedDB(db){const playerKey=currentPid!==null&&DB?.players?.[currentPid]?.[3];await activateDB(db);if(playerKey){const pid=findPidByKey(playerKey);if(pid>=0)selectPlayer(pid)}}
function updateDiagnosticLog(reason,availableVersion=null,error=null){databaseUpdateDiagnostics.localVersion=DB_RECORD?.wzdb_sha256||null;databaseUpdateDiagnostics.availableVersion=availableVersion?.wzdb_sha256||databaseUpdateDiagnostics.availableVersion;databaseUpdateDiagnostics.lastUpdated=DB_RECORD?.lastUpdatedAt||DB_RECORD?.savedAt||null;databaseUpdateDiagnostics.lastError=error?(error.message||String(error)):null;databaseUpdateDiagnostics.lastReason=reason;console.info('[WZDB] Stan aktualizacji',{...databaseUpdateDiagnostics})}
window.getWZDBDiagnostics=()=>({...databaseUpdateDiagnostics});
async function checkDatabaseUpdate({manual=false,firstRun=false,reason='background'}={}){if(updatePromise)return updatePromise;updatePromise=(async()=>{const showProgress=manual||firstRun,previousDB=DB,previousRecord=DB_RECORD;let checkedAt=null,availableVersion=null;databaseUpdateDiagnostics.lastAttempt=new Date().toISOString();databaseUpdateDiagnostics.lastReason=reason;try{const result=await UPDATE.synchronizeDatabase({localRecord:DB_RECORD,fetchVersionImpl:()=>UPDATE.fetchVersion(),downloadDatabaseImpl:version=>UPDATE.downloadDatabase(version),parseDatabase:bytes=>parseWZDB(bytes),persistDatabase:async(db,version,bytes)=>{await saveCustomDB(db,{built:version.built,wzdb_sha256:version.wzdb_sha256,source_sha256:version.source_sha256,lastChecked:checkedAt,lastUpdatedAt:checkedAt},bytes)},activateDatabase:db=>activateUpdatedDB(db),rollbackDatabase:async()=>{if(previousRecord){await idbPut('customDB',previousRecord);DB_RECORD=previousRecord}else{await idbDel('customDB');DB_RECORD=null}if(previousDB)await activateDB(previousDB)},onStage:(stage,payload)=>{if(stage==='checking'){if(showProgress)setProgress('Aktualizacja bazy','Sprawdzam najnowszą wersję WZDB…',12);else if($('dbStatus'))$('dbStatus').textContent='Sprawdzam aktualizacje…'}else if(stage==='checked'){availableVersion=payload.version;checkedAt=new Date().toISOString();lastVersionCheckAt=Date.now();databaseUpdateDiagnostics.lastSuccess=checkedAt;updateDiagnosticLog(reason,availableVersion)}else if(stage==='downloading'&&showProgress)setProgress('Aktualizacja bazy','Pobieram aktualny plik WZDB…',42);else if(stage==='parsing'&&showProgress)setProgress('Aktualizacja bazy','Sprawdzam i rozpakowuję bazę…',72);else if(stage==='persisting'&&showProgress)setProgress('Aktualizacja bazy','Zapisuję bazę na urządzeniu…',88);else if(stage==='activating'&&showProgress)setProgress('Aktualizacja bazy','Buduję indeks wyszukiwania…',96)}});if(!result.updated){DB_RECORD={...DB_RECORD,built:result.version.built,source_sha256:result.version.source_sha256,lastChecked:checkedAt};await idbPut('customDB',DB_RECORD);renderDatabaseMeta();progress(false);if(manual)toast('Baza jest aktualna');return false}progress(false);$('dataModal').classList.add('hidden');updateDiagnosticLog(reason,result.version);toast('Baza danych została zaktualizowana.');return true}catch(e){progress(false);renderDatabaseMeta();updateDiagnosticLog(reason,availableVersion,e);console.error('Aktualizacja WZDB nie powiodła się.',e);if(manual||firstRun||!DB)toast('Błąd aktualizacji: '+(e.message||String(e)));if(!DB){$('sourceName').textContent='Nie udało się pobrać bazy';$('sourceDetails').textContent='Brak sieci nie usuwa zapisanych danych. Po odzyskaniu połączenia aktualizacja zostanie ponowiona.';$('dataModal').classList.remove('hidden')}return false}finally{updatePromise=null}})();return updatePromise}

function requestLifecycleDatabaseCheck(reason,force=false){const lastChecked=lastVersionCheckAt||DB_RECORD?.lastChecked;if(!UPDATE.shouldCheckVersion({online:navigator.onLine!==false,visible:!document.hidden,force,lastChecked}))return;void checkDatabaseUpdate({reason})}

async function activateDB(db){DB=db;STR=db.strings;playerRefs=Array.from({length:DB.players.length},()=>[]);const ys=Object.keys(DB.years).sort((a,b)=>b-a);for(const y of ys){const rows=DB.years[y];for(let i=0;i<rows.length;i++){const pid=rows[i][0];if(playerRefs[pid])playerRefs[pid].push([y,i])}}$('dbInfo').textContent=`${DB.stats.rows.toLocaleString('pl-PL')} wyników • ${DB.stats.from}–${DB.stats.to}`;$('sourceName').textContent=DB.source||'baza danych';$('sourceDetails').textContent=`${DB.stats.rows.toLocaleString('pl-PL')} wyników • ${DB.stats.players.toLocaleString('pl-PL')} zawodników • ${DB.stats.seasons} sezonów (${DB.stats.from}–${DB.stats.to})${DB.imported?' • baza wczytana na urządzeniu':' • baza wbudowana'}`;currentPid=null;currentAll=[];filtered=[];$('q').value='';$('profile').classList.add('hidden');$('filtersPanel').classList.add('hidden');$('resultsSection').classList.add('hidden');$('home').classList.remove('hidden');renderHome()}
async function startup(){try{setProgress('Uruchamianie aplikacji','Sprawdzam zapisaną bazę danych…',20);const stored=await loadStoredDB();if(stored){DB_RECORD=stored.record;setProgress('Uruchamianie aplikacji','Buduję indeks wyszukiwania…',80);await activateDB(stored.db);progress(false);void checkDatabaseUpdate({reason:'startup'});return}await checkDatabaseUpdate({firstRun:true,reason:'first-run'})}catch(e){progress(false);$('dataModal').classList.remove('hidden');toast('Błąd uruchamiania: '+(e.message||String(e)))}}

function renderHome(){const f=favorites().map(k=>findPidByKey(k)).filter(x=>x>=0),r=recents().map(k=>findPidByKey(k)).filter(x=>x>=0);const render=(ids,box,empty)=>{$(box).innerHTML=ids.length?ids.map(pid=>{const p=DB.players[pid],n=playerRefs[pid]?.length||0;return `<div class="quick" data-pid="${pid}"><b>${esc(p[0])}</b><span>${esc(val(p[1])||'—')} • ${n.toLocaleString('pl-PL')} wyników</span></div>`}).join(''):`<div class="empty" style="grid-column:1/-1;padding:12px">${empty}</div>`};renderLatestEvents();render(f,'favGrid','Dodaj gwiazdkę przy profilu zawodnika, aby pojawił się tutaj.');render(r,'recentGrid','Ostatnio otwierani zawodnicy pojawią się tutaj.');document.querySelectorAll('.quick[data-pid]').forEach(x=>x.onclick=()=>selectPlayer(+x.dataset.pid))}
function goHome(){$('profile').classList.add('hidden');$('filtersPanel').classList.add('hidden');$('resultsSection').classList.add('hidden');$('home').classList.remove('hidden');$('q').value='';currentPid=null;renderHome();scrollTo({top:0,behavior:'smooth'})}
function suggestionMeta(pid){const p=DB.players[pid],parts=[];if(val(p[1]))parts.push(val(p[1]));if(p[2])parts.push(fmtBirthDate(p[2]));parts.push(`${(playerRefs[pid]?.length||0).toLocaleString('pl-PL')} wyników`);return parts.join(' • ')}
function rankedPlayers(value,limit=12){return CORE.rankPlayers(playerSearchIndex,value,limit)}
function suggest(){const q=norm($('q').value),box=$('suggest');if(q.length<2){box.classList.add('hidden');return}const hits=rankedPlayers(q,12),fav=new Set(favorites());if(!hits.length){box.innerHTML='<div class="suggestItem"><span>Brak zawodnika</span></div>';box.classList.remove('hidden');return}box.innerHTML=hits.map(({pid})=>{const p=DB.players[pid];return `<div class="suggestItem" data-pid="${pid}"><div><b>${esc(p[0])}</b><span>${esc(suggestionMeta(pid))}</span></div>${fav.has(p[3])?'<i class="suggestFav">★</i>':''}</div>`}).join('');box.classList.remove('hidden');box.querySelectorAll('[data-pid]').forEach(x=>x.onclick=()=>selectPlayer(+x.dataset.pid))}
function findByText(){const hit=rankedPlayers($('q').value,1)[0];if(hit)selectPlayer(hit.pid);else toast('Nie znaleziono zawodnika')}
function addRecent(k){let a=recents().filter(x=>x!==k);a.unshift(k);setList('wz2:recent',a.slice(0,8))}
function updateFavButton(){if(currentPid===null)return;const on=favorites().includes(DB.players[currentPid][3]);$('favBtn').classList.toggle('on',on);$('favBtn').textContent=on?'★':'☆';$('favBtn').title=on?'Usuń z ulubionych':'Dodaj do ulubionych'}
function toggleFav(){if(currentPid===null)return;const k=DB.players[currentPid][3];let a=favorites();if(a.includes(k)){a=a.filter(x=>x!==k);toast('Usunięto z ulubionych')}else{a.unshift(k);toast('Dodano do ulubionych')}setList('wz2:favs',a);updateFavButton();renderHome()}
function selectPlayer(pid){currentPid=pid;const p=DB.players[pid];$('q').value=p[0];$('suggest').classList.add('hidden');$('home').classList.add('hidden');$('profile').classList.remove('hidden');$('filtersPanel').classList.remove('hidden');$('resultsSection').classList.remove('hidden');$('playerName').textContent=p[0];const meta=[];if(val(p[1]))meta.push(val(p[1]));if(p[2])meta.push('ur. '+fmtBirthDate(p[2]));$('playerMeta').textContent=meta.join(' • ')||'Brak dodatkowych danych';currentAll=(playerRefs[pid]||[]).map(([y,i])=>[y,DB.years[y][i]]);addRecent(p[3]);updateFavButton();fillFilters();applyFilters();setTimeout(()=>document.querySelector('#profile').scrollIntoView({behavior:'smooth',block:'start'}),10)}
function options(id,set,first,sorter){const a=[...set].filter(Boolean);if(sorter)a.sort(sorter);else a.sort((x,y)=>x.localeCompare(y,'pl'));$(id).innerHTML=`<option value="">${esc(first)}</option>`+a.map(v=>`<option>${esc(v)}</option>`).join('')}
function fillFilters(){const sets={season:new Set(),league:new Set(),comp:new Set(),track:new Set()};for(const [y,r] of currentAll){sets.season.add(y);sets.league.add(val(r[8]));sets.comp.add(val(r[10]));sets.track.add(val(r[9]))}options('season',sets.season,'Wszystkie sezony',(a,b)=>b-a);options('league',sets.league,'Wszystkie ligi / kraje');options('comp',sets.comp,'Wszystkie rozgrywki');options('track',sets.track,'Wszystkie tory');$('within').value=''}
function applyFilters(){if(currentPid===null)return;shown=60;const fy=$('season').value,fl=$('league').value,fc=$('comp').value,ft=$('track').value,fq=norm($('within').value);filtered=sortResultRefs(currentAll.filter(([y,r])=>{if(fy&&y!==fy)return false;if(fl&&val(r[8])!==fl)return false;if(fc&&val(r[10])!==fc)return false;if(ft&&val(r[9])!==ft)return false;if(fq){const hay=norm([val(r[3]),val(r[4]),val(r[5]),val(r[6]),val(r[7]),val(r[8]),val(r[9]),val(r[10]),val(r[11]),val(r[13])].join(' '));if(!hay.includes(fq))return false}return true}));renderStats();renderPlayerAnalytics();renderResults()}
function clearFilters(){['season','league','comp','track'].forEach(x=>$(x).value='');$('within').value='';applyFilters()}
function renderStats(){const pts=filtered.map(x=>basePoints(val(x[1][1]))).filter(x=>x!==null),avg=pts.length?pts.reduce((a,b)=>a+b,0)/pts.length:null,best=pts.length?Math.max(...pts):null;$('statCount').textContent=filtered.length.toLocaleString('pl-PL');$('statSeasons').textContent=new Set(filtered.map(x=>x[0])).size;$('statAvg').textContent=avg===null?'—':avg.toFixed(2).replace('.',',');$('statBest').textContent=best===null?'—':String(best).replace('.',',');$('resultCount').textContent=`${filtered.length.toLocaleString('pl-PL')} wyników`}
function card(r){const pts=val(r[1])||'—',heats=val(r[2]),e=val(r[3]),f=val(r[4]),g=val(r[5]),h=val(r[6]),score=val(r[7]),league=val(r[8]),track=val(r[9]),comp=val(r[10]),round=val(r[11]),cap=val(r[12]),notes=val(r[13]);const team=!!(g&&h&&score),title=comp||league||'Wynik',sec=[league,track,round].filter(Boolean).join(' • ');let mid='';if(team)mid=`<div class="match"><span><b>${esc(g)}</b> – ${esc(h)}</span><span><b>${esc(score)}</b></span></div>`;else{const ex=[e,f,g,h].filter(Boolean);if(ex.length)mid=`<div class="extras">${esc(ex.join(' • '))}</div>`}const extra=[cap?`Pojemność: ${cap}`:'',notes?`Uwagi: ${notes}`:''].filter(Boolean).join(' • ');return `<article class="card"><div class="cardTop"><div><div class="eventTitle">${esc(title)}</div><div class="secondary">${esc(sec)}</div></div><div class="pts">${esc(pts)}<small>pkt</small></div></div>${mid}${heats?`<div class="heat">Biegi: ${esc(heats)}</div>`:''}${extra?`<div class="extras">${esc(extra)}</div>`:''}</article>`}
function renderResults(){const box=$('results');if(!filtered.length){box.innerHTML='<div class="panel empty">Brak wyników dla wybranych filtrów.</div>';$('loadMore').classList.add('hidden');$('shownInfo').textContent='';return}const part=filtered.slice(0,shown);let html='',last='';for(const [y,r] of part){if(y!==last){html+=`<div class="yearHead"><b>${esc(y)}</b></div>`;last=y}html+=card(r)}box.innerHTML=html;$('loadMore').classList.toggle('hidden',shown>=filtered.length);$('shownInfo').textContent=`Pokazano ${Math.min(shown,filtered.length)} z ${filtered.length}`}

/* Minimal local XLSX/XLSM reader. It only reads the XML parts needed by this database. */
const TD=new TextDecoder('utf-8');
function xmlUnescape(s){return String(s||'').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&apos;/g,"'").replace(/&amp;/g,'&').replace(/&#(\d+);/g,(_,n)=>String.fromCodePoint(+n)).replace(/&#x([0-9a-f]+);/gi,(_,n)=>String.fromCodePoint(parseInt(n,16)))}
function xattr(s,n){const m=s.match(new RegExp('(?:^|\\s)'+n.replace(':','\\:')+'="([^"]*)"'));return m?xmlUnescape(m[1]):''}
class ZipReader{constructor(ab){this.ab=ab;this.dv=new DataView(ab);this.entries=new Map();this.init()}u16(o){return this.dv.getUint16(o,true)}u32(o){return this.dv.getUint32(o,true)}init(){let e=-1,start=Math.max(0,this.ab.byteLength-65557);for(let i=this.ab.byteLength-22;i>=start;i--){if(this.u32(i)===0x06054b50){e=i;break}}if(e<0)throw Error('Nie rozpoznano struktury pliku XLSM/XLSX.');const cnt=this.u16(e+10),off=this.u32(e+16);let p=off;for(let i=0;i<cnt;i++){if(this.u32(p)!==0x02014b50)throw Error('Uszkodzony katalog ZIP w pliku.');const method=this.u16(p+10),cs=this.u32(p+20),us=this.u32(p+24),nl=this.u16(p+28),xl=this.u16(p+30),cl=this.u16(p+32),lo=this.u32(p+42),name=TD.decode(new Uint8Array(this.ab,p+46,nl));this.entries.set(name,{method,cs,us,lo});p+=46+nl+xl+cl}}async bytes(name){const e=this.entries.get(name);if(!e)throw Error('Brak elementu '+name);const p=e.lo,nl=this.u16(p+26),xl=this.u16(p+28),ds=p+30+nl+xl,b=new Uint8Array(this.ab,ds,e.cs);if(e.method===0)return b;if(e.method===8){try{const s=new Blob([b]).stream().pipeThrough(new DecompressionStream('deflate-raw'));return new Uint8Array(await new Response(s).arrayBuffer())}catch{throw Error('Ta przeglądarka nie obsługuje lokalnego odczytu XLSM. Użyj aktualnego Chrome lub Edge.')}}throw Error('Nieobsługiwana metoda kompresji w pliku.')}async text(name){return TD.decode(await this.bytes(name))}}
function resolvePath(base,target){if(target.startsWith('/'))return target.slice(1);const p=base.split('/');p.pop();for(const x of target.split('/')){if(x==='..')p.pop();else if(x!=='.'&&x)p.push(x)}return p.join('/')}
function parseSheets(wb,rels){const rm={};for(const m of rels.matchAll(/<Relationship\b([^>]*)\/?\s*>/g)){const a=m[1],id=xattr(a,'Id'),t=xattr(a,'Target');if(id&&t)rm[id]=resolvePath('xl/workbook.xml',t)}const out=[];for(const m of wb.matchAll(/<sheet\b([^>]*)\/?\s*>/g)){const a=m[1],name=xattr(a,'name'),rid=xattr(a,'r:id');if(name&&rid&&rm[rid])out.push([name,rm[rid]])}return out}
function parseShared(xml){const out=[];for(const m of xml.matchAll(/<si\b[^>]*>([\s\S]*?)<\/si>/g)){let s='';for(const t of m[1].matchAll(/<t(?:\s[^>]*)?>([\s\S]*?)<\/t>/g))s+=xmlUnescape(t[1]);out.push(s)}return out}
function colIndex(ref){const m=ref.match(/^[A-Z]+/);if(!m)return -1;let n=0;for(const ch of m[0])n=n*26+ch.charCodeAt(0)-64;return n-1}
