let playerView='results',rowHomeAwayMap={},teamClassification={events:0,classified:0,rows:0,classifiedRows:0};

const _buildEventIndexV44=buildEventIndex;
buildEventIndex=function(){
  _buildEventIndexV44();rowHomeAwayMap={};teamClassification={events:0,classified:0,rows:0,classifiedRows:0};
  for(const y of Object.keys(DB.years)){const rows=DB.years[y],sides=Array(rows.length).fill('UNKNOWN');rowHomeAwayMap[y]=sides;
    for(const [start,count] of DB.events[y]||[]){const eventRows=rows.slice(start,start+count),first=eventRows[0];if(!first||!val(first[5])||!val(first[6])||!val(first[7]))continue;
      teamClassification.events++;teamClassification.rows+=count;
      const classified=CORE.classifyTeamEvent(eventRows.map(row=>({points:val(row[1]),home:val(row[5]),away:val(row[6]),score:val(row[7])})),{home:val(first[5]),away:val(first[6]),score:val(first[7])});
      if(!classified.classified)continue;teamClassification.classified++;teamClassification.classifiedRows+=count;classified.sides.forEach((side,index)=>{sides[start+index]=side});
    }
  }
};

metricRecords=function(rows){return (rows||[]).map(([season,row,index],fallback)=>{const rowIndex=Number.isInteger(index)?index:fallback,ei=eventFromRow(season,rowIndex),event=ei===null?null:eventData(season,ei);return {season,eventDate:event?.eventDate||'',date:event?.eventDate||'',points:val(row[1]),heats:val(row[2]),startNumber:val(row[14]),league:val(row[8]),track:val(row[9]),competition:val(row[10]),home:val(row[5]),away:val(row[6]),score:val(row[7]),round:val(row[11]),homeAway:rowHomeAwayMap[season]?.[rowIndex]||'UNKNOWN',order:rowIndex,rowIndex,eventKey:ei===null?'':eventRefKeys.get(`${season}:${ei}`)||'',ref:[season,row,rowIndex]}})};

function playerFilterValues(){const tracks=[...advancedTrackSelection];return {season:$('season').value,league:$('league').value,competition:$('comp').value,track:tracks.length?'':$('track').value,tracks,trackMode:advancedTrackMode,search:$('within').value}}
function setSelectOptions(id,values,label,current){const node=$(id),safe=[...values];if(current&&!safe.includes(current))safe.unshift(current);node.innerHTML=`<option value="">${esc(label)}</option>`+safe.map(value=>`<option value="${esc(value)}">${esc(value)}${value===current&&!values.includes(value)?' • poza zakresem':''}</option>`).join('');node.value=current||''}
function refreshPlayerFilterOptions(){if(currentPid===null)return;const filters=playerFilterValues(),available=CORE.cascadingFilterOptions(metricRecords(currentAll),filters);setSelectOptions('season',available.season,'Wszystkie sezony',filters.season);setSelectOptions('league',available.league,'Wszystkie ligi / kraje',filters.league);setSelectOptions('comp',available.competition,'Wszystkie rozgrywki',filters.competition);setSelectOptions('track',available.track,advancedTrackSelection.size?'Tor pojedynczy wyłączony':'Wszystkie tory',filters.track);$('track').disabled=advancedTrackSelection.size>0;renderAdvancedTrackOptions(available.track)}
