  if(analysis.threshold===null){$('thresholdOutput').innerHTML='<div class="panel empty">Wpisz prawidłową wartość progu.</div>';return}
  const newestAnalysis=CORE.sortPlayerResults(analysis.results.map(item=>({...item,...item.record})),'new'),list=newestAnalysis.map(item=>{const r=item.record,click=item.record.eventKey?' clickable':'',when=r.eventDate?fmtDate(r.eventDate):r.season;return `<article class="thresholdRecord${click}" ${item.record.eventKey?`data-threshold-event="${esc(item.record.eventKey)}"`:''}><div><h4>${esc(when)} • ${esc(r.track||r.competition||r.league||'Wynik')}</h4><p>${esc([r.league,r.competition,r.home&&r.away?`${r.home} – ${r.away}`:'',r.homeAway==='HOME'?'dom':r.homeAway==='AWAY'?'wyjazd':''].filter(Boolean).join(' • '))}</p>${r.heats?`<div class="thresholdHeats">Biegi: ${esc(r.heats)}</div>`:''}${r.startNumber?`<div class="thresholdStart">Numer startowy: #${esc(r.startNumber)}</div>`:''}</div><div class="thresholdValue"><b>${esc(r.points||'—')} pkt</b><span class="thresholdBadge ${item.outcome.toLowerCase()}">${item.outcome} ${thresholdNumber(analysis.threshold,1)}</span></div></article>`}).join('');
