function startWord(value){const amount=Math.abs(Number(value)||0),lastTwo=amount%100,last=amount%10;return amount===1?'start':lastTwo>=12&&lastTwo<=14?'startów':last>=2&&last<=4?'starty':'startów'}
function formBlock(title,stats){const availability=stats.available<stats.requested?`<small>Dostępne ${stats.available} ${startWord(stats.available)}</small>`:'';return `<article class="formBlock"><div class="formBlockHead"><b>${title}</b>${availability}</div><div class="formResults">${stats.results.length?stats.results.map(result=>`<span>${esc(result)}</span>`).join(''):'<em>Brak wyników</em>'}</div><div class="formMetrics"><span>Średnia <b>${fmtNum(stats.average)} pkt</b></span><span>Śr. biegowa <b>${fmtNum(stats.heatAverage,3)}</b></span></div></article>`}

