function formChartValue(record,metric){const points=CORE.parsePointsBreakdown(record.points),heats=CORE.parseHeats(record.heats);if(metric==='points')return points.pointsReliable?points.points:null;if(!points.pointsReliable||!heats.rides)return null;const total=points.reliable?points.totalWithBonus:points.points;return total/heats.rides}

function renderFormChart(records){const box=$('formChart'),status=$('formChartValue');if(!box)return;const recent=CORE.lastRecords(records,30),series=recent.map(record=>({record,value:formChartValue(record,formChartMetric)})).filter(item=>item.value!==null);$('formChartToggle').querySelectorAll('[data-form-metric]').forEach(button=>button.classList.toggle('active',button.dataset.formMetric===formChartMetric));if(!series.length){box.innerHTML='<div class="chartEmpty">Brak wiarygodnych danych do wykresu formy.</div>';status.textContent='';return}const moving=series.map((item,index)=>{const window=series.slice(Math.max(0,index-4),index+1);return window.reduce((sum,entry)=>sum+entry.value,0)/window.length}),width=720,height=250,left=38,right=18,top=20,bottom=35,plotW=width-left-right,plotH=height-top-bottom,max=Math.max(1,...series.map(item=>item.value)),min=Math.min(0,...series.map(item=>item.value)),range=Math.max(1,max-min),x=index=>left+(series.length===1?plotW/2:index*plotW/(series.length-1)),y=value=>top+(max-value)*plotH/range;let svg=`<svg class="formChart" viewBox="0 0 ${width} ${height}" role="img" aria-label="Forma zawodnika w kolejnych startach">`;for(let i=0;i<=4;i++){const value=max-range*i/4,gy=top+i*plotH/4;svg+=`<line class="chartGrid" x1="${left}" y1="${gy}" x2="${width-right}" y2="${gy}"></line><text class="chartAxis" x="${left-6}" y="${gy+4}" text-anchor="end">${fmtNum(value,1)}</text>`}if(series.length>1){svg+=`<path class="formResultLine" d="${series.map((item,index)=>`${index?'L':'M'} ${x(index)} ${y(item.value)}`).join(' ')}"></path><path class="movingAverageLine" d="${moving.map((value,index)=>`${index?'L':'M'} ${x(index)} ${y(value)}`).join(' ')}"></path>`}series.forEach((item,index)=>{const record=item.record,heat=formChartValue(record,'heat'),label=[record.season,record.track,record.competition,`${record.points||'—'} pkt`,heat===null?'':`śr. biegowa ${fmtNum(heat,3)}`].filter(Boolean).join(' • ');svg+=`<g class="chartPoint" tabindex="0" data-form-label="${esc(label)}"><circle cx="${x(index)}" cy="${y(item.value)}" r="5"></circle><title>${esc(label)}</title></g>`});svg+='</svg>';box.innerHTML=svg;const show=event=>{status.textContent=event.currentTarget.dataset.formLabel};box.querySelectorAll('[data-form-label]').forEach(point=>{point.addEventListener('pointerenter',show);point.addEventListener('focus',show);point.addEventListener('click',show)});status.textContent=series.at(-1)?.record?[series.at(-1).record.season,series.at(-1).record.track,`${series.at(-1).record.points||'—'} pkt`].filter(Boolean).join(' • '):''}

function comparisonFormCard(player,form,regular){const stats=form.last10;return `<article class="cmpFormCard"><h4>${esc(player[0])}</h4><div class="cmpFormResults"><span>Ostatnie 5</span><b>${esc(form.last5.results.join(' • ')||'—')}</b></div><div class="cmpFormResults"><span>Ostatnie 10</span><b>${esc(stats.results.join(' • ')||'—')}</b></div><div class="cmpFormGrid"><span>Śr. 5 <b>${fmtNum(form.last5.average)}</b></span><span>Śr. biegowa 5 <b>${fmtNum(form.last5.heatAverage,3)}</b></span><span>Śr. 10 <b>${fmtNum(stats.average)}</b></span><span>Śr. biegowa 10 <b>${fmtNum(stats.heatAverage,3)}</b></span><span>Min / max <b>${fmtScore(stats.min)} / ${fmtScore(stats.max)}</b></span><span>Regularność σ <b>${fmtNum(stats.standardDeviation,2)}</b></span></div>${regular?'<small class="regularBadge">bardziej regularny w ostatnich 10</small>':''}</article>`}

function renderComparisonForm(leftRows,rightRows,leftPlayer,rightPlayer){const left=CORE.currentForm(metricRecords(leftRows)),right=CORE.currentForm(metricRecords(rightRows)),ls=left.last10.standardDeviation,rs=right.last10.standardDeviation,leftRegular=ls!==null&&rs!==null&&ls<rs,rightRegular=ls!==null&&rs!==null&&rs<ls;$('cmpForm').innerHTML=`<div class="analyticsTitle"><div><h3>Aktualna forma</h3><p>Ostatnie starty w zakresie wybranych filtrów. Niższe odchylenie oznacza większą regularność.</p></div></div><div class="cmpFormGridCards">${comparisonFormCard(leftPlayer,left,leftRegular)}${comparisonFormCard(rightPlayer,right,rightRegular)}</div>`}

function syncFastControls(){const place=$('thresholdPlace').value,last=$('thresholdLast').value;$('thresholdRangeChips').querySelectorAll('[data-threshold-last]').forEach(button=>button.classList.toggle('active',button.dataset.thresholdLast===last));$('thresholdPlaceChips').querySelectorAll('[data-threshold-place]').forEach(button=>button.classList.toggle('active',button.dataset.thresholdPlace===place));renderQuickProfileFilters()}

function renderQuickProfileFilters(){if(currentPid===null)return;const records=metricRecords(currentAll),seasons=[...new Set(records.map(record=>record.season))].sort((a,b)=>+b-+a),latest=seasons[0]||'',ekstraligaCompetition=records.find(record=>CORE.normalize(record.competition)==='ekstraliga')?.competition||'',ekstraligaLeague=records.find(record=>CORE.normalize(record.league)==='ekstraliga')?.league||'',buttons=[];if(latest)buttons.push({type:'season',value:latest,label:latest,active:$('season').value===latest});if(ekstraligaCompetition)buttons.push({type:'competition',value:ekstraligaCompetition,label:'Ekstraliga',active:$('comp').value===ekstraligaCompetition});else if(ekstraligaLeague)buttons.push({type:'league',value:ekstraligaLeague,label:'Ekstraliga',active:$('league').value===ekstraligaLeague});buttons.push({type:'place',value:'HOME',label:'Dom',active:$('thresholdPlace').value==='HOME'},{type:'place',value:'AWAY',label:'Wyjazd',active:$('thresholdPlace').value==='AWAY'},{type:'last',value:'5',label:'Ostatnie 5',active:$('thresholdLast').value==='5'},{type:'last',value:'10',label:'Ostatnie 10',active:$('thresholdLast').value==='10'});$('quickProfileFilters').innerHTML=buttons.map(item=>`<button class="${item.active?'active':''}" data-quick-type="${item.type}" data-quick-value="${esc(item.value)}">${esc(item.label)}</button>`).join('')+'<button class="clearChip" data-quick-type="clear">× Wyczyść</button>';$('quickProfileFilters').querySelectorAll('[data-quick-type]').forEach(button=>button.onclick=()=>{const type=button.dataset.quickType,value=button.dataset.quickValue;if(type==='season')$('season').value=$('season').value===value?'':value;else if(type==='league')$('league').value=$('league').value===value?'':value;else if(type==='competition')$('comp').value=$('comp').value===value?'':value;else if(type==='place')$('thresholdPlace').value=$('thresholdPlace').value===value?'':value;else if(type==='last')$('thresholdLast').value=$('thresholdLast').value===value?'0':value;else if(type==='clear'){clearProfileFiltersV45();return}applyFilters();persistHistoryContext()})}

function clearProfileFiltersV45(){['season','league','comp','track'].forEach(id=>$(id).value='');$('within').value='';$('thresholdPlace').value='';$('thresholdLast').value='0';advancedTrackSelection.clear();advancedTrackMode='include';advancedTrackQuery='';applyFilters();persistHistoryContext()}

playerScope=function(){const trackScope=advancedTrackSelection.size?`${advancedTrackMode==='exclude'?'bez':'tylko'}: ${[...advancedTrackSelection].join(', ')}`:$('track').value,parts=[$('season').value,$('league').value,$('comp').value,trackScope,$('thresholdPlace').value==='HOME'?'Dom':$('thresholdPlace').value==='AWAY'?'Wyjazd':'',+$('thresholdLast').value?`ostatnie ${$('thresholdLast').value}`:'',$('within').value&&`„${$('within').value.trim()}”`].filter(Boolean);return parts.length?parts.join(' • '):'Cała kariera'};

applyFilters=function(){if(currentPid===null)return;shown=60;const base=CORE.filterRecords(metricRecords(currentAll),playerFilterValues()),place=$('thresholdPlace').value,lastN=+$('thresholdLast').value;profileFilteredModel=CORE.sortPlayerResults(CORE.filterRecords(base,{homeAway:place}),'old');const scoped=CORE.lastRecords(profileFilteredModel,lastN);filtered=CORE.sortPlayerResults(scoped,sortMode).map(record=>record.ref);refreshPlayerFilterOptions();renderStats();renderPlayerAnalytics();renderResults();renderCurrentForm();$('playerScope').textContent=playerScope();renderThreshold();syncFastControls()};

const _renderThresholdV45=renderThreshold;
renderThreshold=function(){_renderThresholdV45();if(currentPid===null||!$('thresholdOutput')||!profileFilteredModel.length){syncFastControls();return}const line=$('thresholdLine').value,pointsMode=$('thresholdPoints').value,lastN=+$('thresholdLast').value,analysis=CORE.analyzeThreshold(profileFilteredModel,line,{pointsMode,lastN}),trend=CORE.thresholdTrend(profileFilteredModel,line,{pointsMode}),summary=$('thresholdOutput').querySelector('.thresholdSummary'),sample=$('thresholdOutput').querySelector('.thresholdSample');if(summary){const streak=trend.streak.outcome?`${trend.streak.count} × ${trend.streak.outcome}`:'—';summary.insertAdjacentHTML('afterend',`<div class="thresholdTrends"><span>Ostatnie 5 <b>OVER ${trend.last5.over}/${trend.last5.sample}</b></span><span>Ostatnie 10 <b>OVER ${trend.last10.over}/${trend.last10.sample}</b></span><span>Aktualna seria <b>${streak}</b></span></div>`)}if(sample){let warning='';if(analysis.sample>=1&&analysis.sample<=5)warning='<div class="sampleWarning">⚠ Mała próba – wynik może być mało reprezentatywny.</div>';else if(analysis.sample<=10&&analysis.sample>5)warning='<div class="sampleWarning limited">⚠ Ograniczona próba – interpretuj wynik ostrożnie.</div>';sample.innerHTML=`Próba: <b>${analysis.sample} ${analysis.sample===1?'start':'startów'}</b>${warning}`}syncFastControls()};

$('thresholdRangeChips').innerHTML=[['5','Ostatnie 5'],['10','Ostatnie 10'],['20','Ostatnie 20'],['0','Wszystkie']].map(([value,label])=>`<button data-threshold-last="${value}">${label}</button>`).join('');
$('thresholdPlaceChips').innerHTML=[['','Wszystkie'],['HOME','Dom'],['AWAY','Wyjazd']].map(([value,label])=>`<button data-threshold-place="${value}">${label}</button>`).join('');
